def tuplerize(method):
    def wrap(*args, **kwargs):
        res = method(*args, **kwargs)
        if not isinstance(res, (tuple, list)):
            res = (res, )

        return res
    return wrap

''' Solution '''
@tuplerize
def solve(s):
    def is_palindrome(x):
        for i in range(len(x)//2):
            if x[i] != x[-1-i]:
                return False

        return True

    def execute(d, cmds):
        for cmd in cmds:
            _dir, l = cmd.split(' ')
            l = int(l)

            if _dir == 'R':
                d = d + ''.join([x for x in reversed(d[l-1:-1])])
            else:
                d = ''.join([x for x in reversed(d[1:l])]) + d


        return d

    if is_palindrome(s):
        return 0

    res = [
        'R {}'.format(len(s) - 1),
        'L {}'.format(len(s)),
        'L 2'
    ]

    if is_debug():
        p = execute(s, res)
        print('Verify', p, is_palindrome(p))

    return '{}\n{}'.format(
        len(res),
        '\n'.join(res))

print(*solve(get_str()))

