def soln(s):
    founds1 = []
    founds2 = []
    j = float('-inf') 
    for i in range(len(s) - 1):
        # print(i, j)
        c1 = s[i]
        c2 = s[i + 1]
        if c1 == 'A' and c2 == 'B':
            founds1.append(i)
        elif c1 == 'B' and c2 == 'A':
            founds2.append(i)
    if len(founds1) == 0 or len(founds2) == 0:
        return 'NO'
    if len(founds1) >= 3 or len(founds2) >= 3:
        return 'YES'
    # if abs(founds1[0] - founds2[0]) == 1:
    #     return 'NO'
    for i in founds1:
        for j in founds2:
            if abs(i - j) > 1:
                return 'YES'
    return 'NO'

def main():
    s = input()
    result = soln(s)
    print(result)

if __name__ == '__main__':
    main()

