def votes(aa):
    x, y, z = aa[0], aa[1], aa[2]
    if x > y:
        if x > y+z:
            return "+"
        return "?"
    elif x < y:
        if y > x+z:
            return "-"
        return "?"
    elif x == y and z == 0:
        return 0
    else:
        return "?"

n = list(map(int, input().split()))
print(votes(n))
